// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint256 amount, uint256 seed) public {
        vm.assume(amount >= 0);
        vm.assume(seed <= 10);
        address dummyVader = address(uint160(uint256(keccak256(abi.encode(seed)))));
        address dummyUsdv = address(uint160(uint256(keccak256(abi.encode(seed + 1)))));
        address dummyVault = address(uint160(uint256(keccak256(abi.encode(seed + 2)))));
        c.init(dummyVader, dummyUsdv, dummyVault);
        uint256 startCount = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        uint256 endCount = c.proposalCount();
        assertTrue(endCount == startCount + 1);
    }
}
